import{_ as t,l,o,c as i,v as e,p as s,x as n,d as E,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"商品展期 alpha","description":"","frontmatter":{"title":"商品展期 alpha","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/commodity-roll-alpha.md","filePath":"quant/commodity-roll-alpha.md","lastUpdated":1789023840000}'),d={name:"quant/commodity-roll-alpha.md"};function A(B,a,m,u,c,_){const r=l("Mermaid");return o(),i("div",null,[a[1]||(a[1]=e('<h1 id="商品展期-alpha" tabindex="-1">商品展期 alpha <a class="header-anchor" href="#商品展期-alpha" aria-label="Permalink to &quot;商品展期 alpha&quot;">​</a></h1><div class="epigraph"><p>完全抵押的商品期货多头，收益并不等于现货涨了多少；把近月换成远月时锁定的价差，是这个资产类别里可重复的一块，也是横截面上可排序的一块。</p><footer>—— Gorton &amp; Rouwenhorst, Facts and Fantasies about Commodity Futures, Financial Analysts Journal, 2006；期限溢价分解见 Szymanowska et al., Journal of Finance, 2014</footer></div><p><a href="/quant/xccy-basis">上一课</a>把交叉货币基差写成市场远期相对 OIS-CIP 远期的修正，必须作为输入曲面；它不是 UIP 套息，也不是 NDF 可兑换性溢价。外汇基差不回答商品指数为什么赚钱。Gorton 与 Rouwenhorst 确立商品期货作为资产类别的平均事实，超额很大程度来自期货市场本身。缺口是把平均变成可交易横截面：按基差、库存或基差动量在品种与到期之间排序，并避开机械滚仓窗。展期 alpha 是仓储语言的交易层。本课写跨品种与跨到期的可移植规则；同一品种内部按季节选月，见 <a href="/quant/seasonal-roll">季节性展期</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全抵押的近月期货超额，近似拆成现货收益加展期收益加抵押利息。现货腿波动大、长期漂移在许多品种上并不稳；展期腿由 \\(F_{\\mathrm{near}}/F_{\\mathrm{next}}\\) 决定，慢且与库存周期相关。指数（GSCI、BCOM）用固定的滚仓窗和固定的近月规则，把所有品种的展期平均进一个 beta。问题是平均里既有正展期的石油与部分农产品，也有长期 contango 的某些金属与畜产品。被动多头在后一类上持续付展期。alpha 来自拒绝这一平均：按预期展期排序，空头那些系统付费的品种，或多头更远的合约以减轻负展期。</p><p>第二层是拥挤。指数滚仓窗事先公开。Mou（2011）提供证据：在高盛指数传统滚仓日前，相关合约的价格朝不利于指数的方向移动——前跑机械需求。机械近月策略的部分「负 alpha」其实是执行，不是仓储理论失效。展期 alpha 必须同时设计<strong>信号</strong>（谁该持有）与<strong>日历</strong>（何时换月）。</p><h3 id="现货溢价与期限溢价" tabindex="-1">现货溢价与期限溢价 <a class="header-anchor" href="#现货溢价与期限溢价" aria-label="Permalink to &quot;现货溢价与期限溢价&quot;">​</a></h3><p>Szymanowska 等人（2014）的解剖：持有近月暴露的是现货溢价（与现货风险相关的补偿）；在曲线上做多一个到期、做空另一个，暴露期限溢价。二者都与基差有关，但不是同一个组合。只做「全市场多头商品」的人把两块捆在一起；只做日历价差的人几乎只要第二块。文献里不少「基差策略」混着两条腿。实现上应分别记账：横截面多空近月（现货溢价加展期），以及品种内日历价差（更纯的期限溢价）。Gorton、Hayashi 与 Rouwenhorst（2013）表明低库存品种随后收益更高——这主要给第一块提供基本面；期限溢价还依赖曲线斜率是否已被定价过度。</p><p><span class="marginnote">Erb 与 Harvey 指出，指数的再平衡本身会产生分散化收益。那不是展期 alpha：即使曲线全是平坦的，波动率与再平衡规则也能造出与几何平均有关的项。归因时应把再平衡、抵押利息、展期、现货四项分开，否则会把波动率当仓储。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>信号。最简单的是基差或展期收益率 \\(\\rho=\\ln(F_1/F_2)/\\Delta T\\)，按品种排序，多头最高分位、空头最低分位，定期再平衡。可用库存分位、仓单、便利收益反演代替或增强 \\(\\rho\\)，这与 <a href="/quant/commodity-inventory">库存与曲线</a> 一致。Boons 与 Prado 的基差动量：用基差的近期变化，捕捉紧张加剧或缓解。不要把十二个月现货动量与展期信号无说明地乘在一起——Gorton 等人已指出动量部分来自选出低库存品种；乘积因子要能在控制基差后仍显著，才算新东西。</p><p>合约选择。在允许的流动性月份里，避开即将进入指数滚仓窗或即将交割的合约；对持续 contango 的品种，持有次近月或更远的活跃月，降低负展期（牺牲一些 Samuelson 波动与部分现货溢价）。这是对 Erb–Harvey「战术价值」的可操作化，也是对 Mou 前跑的规避。</p><p>组合。商品之间相关在危机中上升，多空展期不是市场中性到可以无限杠杆。波动目标应基于曲线状态：低库存、高 \\(y\\) 时近月方差大，按名义等权会在紧张品种上超配风险。Gorton–Rouwenhorst 的长期等权多头是资产配置陈述；alpha 组合是相对价值陈述，二者杠杆与回撤预算不应共用。</p><h3 id="回测中的换月会计" tabindex="-1">回测中的换月会计 <a class="header-anchor" href="#回测中的换月会计" aria-label="Permalink to &quot;回测中的换月会计&quot;">​</a></h3><p>必须在单合约价格上模拟买卖价差与滚仓。主连连续序列往往已按某种规则调整过跳空，用它计算「展期收益」会重复或抹掉真实现金流。滚仓应在数日内完成，而不是假定结算价一次性换月。容量：指数品种的近月深度尚可，远月与小品种会迅速恶化。把 illiquid 远月写进最优展期，样本外滑点会吞掉 Szymanowska 意义上的期限溢价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>仓储机制给出符号：低库存 → 高便利收益 → 近月升水 → 多头展期正期望，见 Kaldor、Working 与 Gorton–Hayashi–Rouwenhorst。横截面排序等于在交易 \\(y(I)\\) 的截面。凯恩斯（1930）与希克斯（1939）的套保压力给出另一条符号故事：净生产商套保的品种远期偏低。两条故事在低库存且生产商套保时同向；在消费商套保或金融多头拥挤时可能冲突。实证赛马把预测权更多地给库存与基差，而不是给 CFTC 净持仓。因此展期 alpha 的一阶应是曲线与库存，套保压力最多当正交检验。</p><p>金融需求机制给出执行：指数与 ETN 的滚仓是可预测的订单流。前跑与拥挤使机械近月的实现展期差于「用结算价算的纸面展期」。聪明滚仓的 alpha 有一块是不做别人必须做的那笔流动性需求，而不是发现了新的 Working 曲线。</p><p><span class="marginnote">把展期 alpha 写成「永远做多整个商品指数」并不被 Gorton–Rouwenhorst 支持到可以忽略品种选择。他们的平均事实依赖样本与等权；Erb–Harvey 对单个品种长期收益的警告仍然有效。alpha 是相对的。</span></p><h3 id="与外汇套息的类比与限度" tabindex="-1">与外汇套息的类比与限度 <a class="header-anchor" href="#与外汇套息的类比与限度" aria-label="Permalink to &quot;与外汇套息的类比与限度&quot;">​</a></h3><p>商品展期像外汇套息：都是持有高利差（这里是正基差）资产、做空低利差。UIP 在外汇失败，仓储理论在商品上给出更硬的基本面——库存可测，\\(y\\) 可反演。限度是：商品有交割与仓储极限（曲线可以断），外汇 G10 没有同等的「满罐」。危机中商品多空会一起碰到流动性；套息会碰到美元短缺。不要把 Du–Tepper–Verdelhan 的 CIP 基差因子直接当商品展期的对冲工具。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>超级周期与金融化改变谁在曲线上、不自动废除 \\(y(I)\\)，但会改变近月的平均 contango（2000 年代中期之后部分指数品种更常付展期）。样本必须跨过这一段再下结论。负油价、交割地点失效时，近月信号无定义，应有停机规则。碳排放、电力、部分运费合约的「展期」更接近期限结构风险溢价，缺乏稳定库存测量，不宜与原油农产品混成同一分位。</p><p>不要用 PPP 或 CIP 的语言去包装商品展期。卡塞尔锚的是汇率与物价；凯恩斯—希克斯在商品里要落到库存与套保，而不是落到利率平价。文献引用应停在仓储、Gorton–Rouwenhorst、Szymanowska、Erb–Harvey、Mou、Boons–Prado 这一支。</p><p><span class="marginnote">纸面夏普常来自在结算价上瞬间换月、忽略限仓与交割通知。实盘的展期 alpha 是扣掉这些之后仍与库存分位同向的那一段。若只在拥挤窗口里相对指数做价差，你交易的是 Mou 的订单流，应如实命名。</span></p>',25)),(o(),s(p,null,{default:n(()=>[h(r,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%BA%93%E5%AD%98%E4%B8%8E%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%20y(I)%22%5D%20--%3E%20BAS%5B%22%E5%9F%BA%E5%B7%AE%20%2F%20%E5%B1%95%E6%9C%9F%E6%94%B6%E7%9B%8A%E7%8E%87%22%5D%0A%20%20BAS%20--%3E%20XS%5B%22%E6%A8%AA%E6%88%AA%E9%9D%A2%3A%20%E5%A4%9A%20backwardation%20%E7%A9%BA%20contango%22%5D%0A%20%20BAS%20--%3E%20TERM%5B%22%E5%93%81%E7%A7%8D%E5%86%85%3A%20%E6%9C%9F%E9%99%90%E6%BA%A2%E4%BB%B7%20%2F%20%E6%97%A5%E5%8E%86%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20IDX%5B%22%E6%8C%87%E6%95%B0%E6%9C%BA%E6%A2%B0%E6%BB%9A%E4%BB%93%22%5D%20--%3E%20FR%5B%22%E5%89%8D%E8%B7%91%E4%B8%8E%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20FR%20--%3E%20SMART%5B%22%E5%90%88%E7%BA%A6%E9%80%89%E6%8B%A9%E4%B8%8E%E9%94%99%E5%BC%80%E6%BB%9A%E4%BB%93%22%5D%0A%20%20XS%20--%3E%20PNL%5B%22%E5%AE%9E%E7%8E%B0%E7%9A%84%E5%B1%95%E6%9C%9F%20alpha%22%5D%0A%20%20TERM%20--%3E%20PNL%0A%20%20SMART%20--%3E%20PNL%0A%20%20SPOT%5B%22%E7%8E%B0%E8%B4%A7%E6%BA%A2%E4%BB%B7%22%5D%20--%3E%20NEAR%5B%22%E8%BF%91%E6%9C%88%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20XS%20--%3E%20NEAR%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gorton 与 Rouwenhorst（2006）确立商品期货作为资产类别的平均事实；展期是平均超额的核心成分，但平均不等于最优。</li><li>展期 alpha 是按基差、库存或基差动量在品种与到期之间排序，并避开机械滚仓窗（Erb and Harvey, 2006；Szymanowska et al., 2014；Boons and Prado, 2019；Mou, 2011）。</li><li>机制一阶是仓储与 \\(y(I)\\)（Working；Gorton, Hayashi and Rouwenhorst, 2013），不是把凯恩斯套保压力当默认因子。</li><li>现货溢价与期限溢价应分开记账；主连连续行情不能用来回测展期现金流。</li><li>与季节性展期、便利收益、库存—曲线是同一套仓储语言的交易层；与外汇 CIP/PPP 不是同一套。</li><li>出处：Gorton and Rouwenhorst, <em>Financial Analysts Journal</em>, 2006；Erb and Harvey, <em>FAJ</em>, 2006；Gorton, Hayashi and Rouwenhorst, <em>Review of Finance</em>, 2013；Szymanowska, de Roon, Nijman and van den Goorbergh, <em>Journal of Finance</em>, 2014；Boons and Prado, <em>Journal of Finance</em>, 2019；Mou, 2011；凯恩斯与希克斯见 <em>A Treatise on Money</em>, 1930 与 <em>Value and Capital</em>, 1939。</li></ul>',2))])}const b=t(d,[["render",A]]);export{y as __pageData,b as default};
